u2_notes = {1: "Subject of «φαίνονται», referring to «Τα έργα του» (neuter plural): τα οποία.",
            2: "Ακόμα και (even) + time phrase; «Ακόμα κι αν» would need a verb.",
            3: "Two simultaneous developments: ενώ (while).",
            4: "αντί να (instead of) + verb.",
            5: "Masculine plural, referring to «Πολλοί από αυτούς» (the students): ανάμεσα στους οποίους."}
o2 = u2_ans + u2_dis; rnd.shuffle(o2)
